package com.bank.report;

import java.util.Optional;

// Demonstrates safe concatenation vs an unsafe method call on null.
class TransactionFormatter {

    // SAFE: concatenating a null remark yields the literal "null" — no exception.
    String describeNaive(Transaction t) {
        return "Txn " + t.getTxnId() + " amount " + t.getAmount()
                + " remark: " + t.getRemark(); // null becomes "null"
    }

    // UNSAFE: calling length() on a possibly-null remark throws NPE.
    int remarkLengthUnsafe(Transaction t) {
        return t.getRemark().length(); // NPE if remark is null
    }

    // SAFE display: convert null to a readable placeholder.
    String describeSafe(Transaction t) {
        String remark = Optional.ofNullable(t.getRemark()).orElse("(no remark)");
        return "Txn " + t.getTxnId() + " amount " + t.getAmount() + " remark: " + remark;
    }

    // SAFE length: guard before calling the method.
    int remarkLengthSafe(Transaction t) {
        String remark = t.getRemark();
        return remark == null ? 0 : remark.length();
    }
}
