package com.bank.report;

import java.math.BigDecimal;
import java.util.logging.*;

public class NullHandlingDemo {
    private static final Logger log = Logger.getLogger(NullHandlingDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        TransactionFormatter fmt = new TransactionFormatter();

        // A transaction with NO remark (remark is null).
        Transaction t = new Transaction("TXN-77", new BigDecimal("50000"), null);

        // 1) SAFE concatenation prints "null" literally.
        log.info(() -> "Concatenation: " + fmt.describeNaive(t));

        // 2) UNSAFE method call on null throws NullPointerException.
        try {
            int len = fmt.remarkLengthUnsafe(t);
            log.info(() -> "Unsafe length: " + len);
        } catch (NullPointerException e) {
            log.log(Level.SEVERE, "Calling length() on null remark threw NPE", e);
        }

        // 3) SAFE display with a placeholder instead of "null".
        log.info(() -> "Safe display: " + fmt.describeSafe(t));

        // 4) SAFE length with a null guard.
        log.info(() -> "Safe length: " + fmt.remarkLengthSafe(t));

        // 5) Direct demonstration of the two behaviours side by side.
        String nullString = null;
        log.info(() -> "\"Value: \" + nullString -> " + ("Value: " + nullString));
        try {
            int n = nullString.length();
            log.info(() -> "nullString.length() -> " + n);
        } catch (NullPointerException e) {
            log.warning(() -> "nullString.length() -> threw NullPointerException");
        }
    }
}

